document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openBatchTrim">Trim multiple clips</button><button id="openBatchKeys">Edit multiple keys</button>');
function projectClipRecords(p=project){const clips=[];let offset=0;for(const s of p.scenes){for(const o of s.objects)clips.push({ref:'v:'+o.id,id:o.id,kind:'visual',sceneId:s.id,name:o.name,start:offset+clipStart(o),end:offset+clipEnd(o,s),locked:!!o.locked});offset+=s.duration}for(const c of p.audioClips||[])clips.push({ref:'a:'+c.id,id:c.id,kind:'audio',name:c.name,start:c.start,end:audioEnd(c),locked:!!c.locked});return clips}
function planBatchTrim(refs,side,delta){if(!['left','right'].includes(side)||!Number.isFinite(delta)||Math.abs(delta)>60||!refs.length)throw Error('Select clips, an edge and a change of up to 60 seconds.');const copy=structuredClone(project),original=projectClipRecords(),selected=new Set(refs),allObjects=copy.scenes.flatMap(s=>s.objects);for(const ref of selected){if(ref.startsWith('v:'))for(const c of copy.audioClips||[])if(c.videoId===ref.slice(2))selected.add('a:'+c.id);if(ref.startsWith('a:')){const c=copy.audioClips.find(c=>c.id===ref.slice(2));if(c?.videoId)selected.add('v:'+c.videoId)}}let offset=0;for(const s of copy.scenes){for(const o of s.objects){if(!selected.has('v:'+o.id))continue;if(o.locked)throw Error('Unlock '+o.name+' before batch trimming.');const start=clipStart(o),end=clipEnd(o,s),nextStart=side==='left'?start+delta:start,nextEnd=side==='right'?end+delta:end;if(nextStart<0||nextEnd>s.duration+.001||nextEnd-nextStart<.1)throw Error(o.name+': keep a clip of at least 0.1 seconds inside its scene.');if(o.type==='video'){if(side==='left')o.sourceOffset+=delta*videoSpeed(o);if(o.sourceOffset<0||o.sourceOffset+(nextEnd-nextStart)*videoSpeed(o)>o.sourceDuration+.001)throw Error(o.name+': the source video does not cover that trim.')}o.in=nextStart;o.out=nextEnd;for(const c of copy.audioClips||[])if(c.videoId===o.id){if(c.locked)throw Error('Unlock '+c.name+' before trimming its video.');c.start=offset+nextStart;c.offset=o.sourceOffset;c.rate=videoSpeed(o);c.duration=Math.min(nextEnd-nextStart,(c.sourceDuration-c.offset)/c.rate);const fades=fadeDurations(c);c.fadeIn=fades.in;c.fadeOut=fades.out}}offset+=s.duration}
 const total=copy.scenes.reduce((n,s)=>n+s.duration,0);for(const c of copy.audioClips||[]){if(!selected.has('a:'+c.id)||c.videoId&&selected.has('v:'+c.videoId))continue;if(c.locked)throw Error('Unlock '+c.name+' before batch trimming.');const rate=c.rate||1;if(side==='left'){c.start+=delta;c.offset+=delta*rate;c.duration-=delta}else c.duration+=delta;if(c.start<0||c.offset<0||c.duration<.05||audioEnd(c)>total+.001||c.offset+c.duration*rate>c.sourceDuration+.001)throw Error(c.name+': keep the audio trim inside the source and project.');const fades=fadeDurations(c);c.fadeIn=fades.in;c.fadeOut=fades.out}
 offset=0;for(const s of copy.scenes){for(const line of storyLines(s)){const c=copy.audioClips?.find(c=>c.id===line.audioId);if(c&&selected.has('a:'+c.id)){line.start=c.start-offset;line.manualStart=line.start;line.duration=c.duration;if(line.start<0||line.start+line.duration>s.duration+.001)throw Error('Keep this arranged dialogue voice inside its scene.')}}offset+=s.duration}if(!valid(copy))throw Error('The trim would leave invalid linked media or timing.');const after=projectClipRecords(copy),entries=[...selected].map(ref=>({before:original.find(c=>c.ref===ref),after:after.find(c=>c.ref===ref)}));if(entries.some(e=>!e.before||!e.after))throw Error('The selected clips changed. Open the tool again.');return{source:JSON.stringify(project),project:copy,entries,side,delta}}
function applyBatchTrim(plan){if(!plan||plan.source!==JSON.stringify(project))throw Error('The project changed. Preview the trim again.');project.scenes=plan.project.scenes;project.audioClips=plan.project.audioClips;for(const s of project.scenes)if(typeof retimeStoryShots==='function')retimeStoryShots(s);stop();save();render()}
document.body.insertAdjacentHTML('beforeend','<dialog id="batchTrimDialog"><div class="tool-heading"><h2>Trim multiple clips</h2><button id="closeBatchTrim">Close</button></div><p class="note">Choose the clips and review their new in/out points. Linked video and its original sound stay together. This changes selected edges without rippling other clips.</p><div id="batchClipChoices" class="batch-choice-list"></div><div class="rig-tools"><label>Edge<select id="batchTrimSide"><option value="right">End</option><option value="left">Beginning</option></select></label><label>Move edge by (s)<input id="batchTrimDelta" type="number" min="-60" max="60" step="0.033333" value="-0.5"></label><button id="previewBatchTrim">Preview changes</button><button id="applyBatchTrim" class="primary" disabled>Apply reviewed trim</button></div><p id="batchTrimStatus" role="status" class="note"></p><div id="batchTrimResults" class="ease-card-list"></div></dialog>');
function openBatchTrim(){if(recording||audioBusy)return;stop();batchTrimPreview=null;batchClipSelection=new Set([...selectedLayers().map(o=>'v:'+o.id),...(selectedAudio?['a:'+selectedAudio]:[])]);const offset=sceneOffset(),end=offset+current().duration,list=$('batchClipChoices');list.replaceChildren();for(const clip of projectClipRecords().filter(c=>c.kind==='visual'?c.sceneId===current().id:c.start<end&&c.end>offset)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=batchClipSelection.has(clip.ref);input.onchange=()=>{input.checked?batchClipSelection.add(clip.ref):batchClipSelection.delete(clip.ref);batchTrimPreview=null;$('applyBatchTrim').disabled=true};label.append(input,document.createTextNode(clip.name+' · '+clip.start.toFixed(2)+'–'+clip.end.toFixed(2)+'s'+(clip.locked?' · locked':'')));list.append(label)}$('batchTrimResults').replaceChildren();$('batchTrimStatus').textContent='Positive values move the selected edge later; negative values move it earlier.';$('applyBatchTrim').disabled=true;$('batchTrimDialog').showModal()}
$('openBatchTrim').onclick=openBatchTrim;$('closeBatchTrim').onclick=()=>$('batchTrimDialog').close();$('previewBatchTrim').onclick=()=>{try{batchTrimPreview=planBatchTrim([...batchClipSelection],$('batchTrimSide').value,+$('batchTrimDelta').value);const list=$('batchTrimResults');list.replaceChildren();for(const e of batchTrimPreview.entries){const row=document.createElement('div');row.className='ease-entry';row.textContent=e.before.name+': '+e.before.start.toFixed(2)+'–'+e.before.end.toFixed(2)+'s → '+e.after.start.toFixed(2)+'–'+e.after.end.toFixed(2)+'s';list.append(row)}$('batchTrimStatus').textContent=batchTrimPreview.entries.length+' clips ready. The project is unchanged until Apply.';$('applyBatchTrim').disabled=false}catch(e){batchTrimPreview=null;$('applyBatchTrim').disabled=true;$('batchTrimStatus').textContent=e.message}};$('applyBatchTrim').onclick=()=>{try{applyBatchTrim(batchTrimPreview);batchTrimPreview=null;$('applyBatchTrim').disabled=true;$('batchTrimStatus').textContent='Trim applied. Undo restores all affected clips.'}catch(e){$('batchTrimStatus').textContent=e.message}};for(const id of ['batchTrimSide','batchTrimDelta'])$(id).oninput=()=>{batchTrimPreview=null;$('applyBatchTrim').disabled=true};
function layerKeyRecords(o){const records=[],add=(kind,track,key,index,t)=>records.push({ref:kind+':'+track+':'+index,kind,track,index,time:t,data:structuredClone(key)});o.keys.forEach((k,i)=>add('pose','main',k,i,k.t));for(const[region,track]of Object.entries(o.bodyAnimation||{}))track.keys.forEach((k,i)=>add('body',region,k,i,k.t));for(const[field,keys]of Object.entries(o.objectAnimation||{}))keys.forEach((k,i)=>add('part',field,k,i,k.t));for(const[kind,field]of[['expression','expressionKeys'],['view','viewKeys'],['hand','handGestureKeys']])(o[field]||[]).forEach((k,i)=>add(kind,field,k,i,k.t));(o.wordAnimation?.words||[]).forEach((k,i)=>add('word','words',k,i,k.start));return records.sort((a,b)=>a.time-b.time||a.kind.localeCompare(b.kind))}
function keyRecordArray(o,record,create=false){if(record.kind==='pose')return o.keys;if(record.kind==='body')return(create?bodyTrack(o,record.track):o.bodyAnimation?.[record.track])?.keys;if(record.kind==='part'){if(!partDefinitions(o)[record.track]||o.explainerAsset?.style!=='vector')throw Error('This target has no matching '+record.track+' part.');return create?(o.objectAnimation??={})[record.track]??=[]:o.objectAnimation?.[record.track]}if(record.kind==='word'){if(o.type!=='text'||record.data.index>=textWords(o.text).length)throw Error('This target has no matching word.');if(create)o.wordAnimation??={source:o.text,words:[]};return o.wordAnimation?.words}if(record.kind==='view'&&(o.type!=='puppet'||!o.characterViews?.[record.data.view]))throw Error('Prepare the matching character view before pasting its key.');if(['expression','hand'].includes(record.kind)&&!isAnimatedCharacter(o))throw Error('Choose a character for these performance keys.');if(create)o[record.track]??=[];return o[record.track]}
function removeKeyRecords(o,records){const byArray=new Map();for(const record of records){const array=keyRecordArray(o,record);if(!array)continue;const set=byArray.get(array)||new Set();set.add(record.index);byArray.set(array,set)}for(const [array,indices]of byArray)for(const index of [...indices].sort((a,b)=>b-a))array.splice(index,1);if(!o.keys.length)throw Error('Keep at least one main pose key.')}
function insertKeyRecord(o,record,at,{absolute=false,positionOffset=null}={}){const key=structuredClone(record.data),array=keyRecordArray(o,record,true);if(record.kind==='body'){if(!isAnimatedCharacter(o))throw Error('Choose a character for body keys.');key.v=Object.fromEntries(Object.entries(key.v).filter(([f])=>bodyFieldAvailable(o,f)));if(!Object.keys(key.v).length)throw Error('This rig has no matching joint controls.');if(absolute&&o.bodyAnimation[record.track].mode==='add'){const base=poseBeforeBodyAnimation(o,at);for(const f of Object.keys(key.v))key.v[f]-=base[f]}}if(record.kind==='pose'&&positionOffset){key.v.x+=positionOffset.x;key.v.y+=positionOffset.y}if(record.kind==='word'){key.start=at;if(at+key.duration>current().duration+.001)throw Error('Keep the word movement inside the scene.');const existing=array.findIndex(k=>k.index===key.index);if(existing>=0)array.splice(existing,1,key);else array.push(key);o.wordAnimation.source=o.text}else{key.t=at;const existing=array.findIndex(k=>Math.abs(k.t-at)<.001);if(existing>=0)array[existing]=record.kind==='body'?{...array[existing],...key,v:{...array[existing].v,...key.v}}:key;else array.push(key);array.sort((a,b)=>a.t-b.t)}if(array.length>500)throw Error('Keep up to 500 keys per track.')}
function buildKeyEdit(o,records,operation,{delta=0,at=time,keepPosition=true,clipboard=batchKeyClipboard}={}){if(!o||o.locked)throw Error('Choose an unlocked target layer.');const copy=structuredClone(o),selected=records||[];if(operation==='shift'){if(!Number.isFinite(delta))throw Error('Enter a finite shift.');if(!selected.length)throw Error('Select some keys first.');const remaining=layerKeyRecords(o).filter(r=>!selected.some(s=>s.ref===r.ref));for(const record of selected){const next=record.time+delta;if(next<0||next>current().duration||remaining.some(r=>r.kind===record.kind&&r.track===record.track&&Math.abs(r.time-next)<.001))throw Error('The shift would leave the scene or overwrite an unselected key.')}const placeholders=selected.filter(r=>r.kind==='pose').length===copy.keys.length;if(placeholders)copy.keys.push({t:-1,v:{...pose,...rigDefaults}});removeKeyRecords(copy,selected);if(placeholders)copy.keys=copy.keys.filter(k=>k.t!==-1);for(const record of selected)insertKeyRecord(copy,record,Math.round((record.time+delta)*1000)/1000)}else if(operation==='paste'){if(!clipboard?.items?.length||clipboard.items.length>500)throw Error('Copy some keys first.');const first=clipboard.items.find(r=>r.kind==='pose'),target=rawStateAt(o,at),positionOffset=keepPosition&&first?{x:target.x-first.data.v.x,y:target.y-first.data.v.y}:null;for(const record of clipboard.items){const t=at+record.relative;if(!Number.isFinite(t)||t<0||t>current().duration+.001)throw Error('Keep pasted keys inside this scene.');insertKeyRecord(copy,record,Math.round(t*1000)/1000,{absolute:record.kind==='body',positionOffset})}}else if(operation==='delete'){removeKeyRecords(copy,selected)}else throw Error('Choose a key edit.');if(!valid({...project,scenes:project.scenes.map(s=>s===current()?{...s,objects:s.objects.map(a=>a.id===o.id?copy:a)}:s)}))throw Error('These keys are incompatible with the target or exceed valid timing limits.');return copy}
function copyLayerKeys(o,records){if(!records.length||records.length>500)throw Error('Copy 1 to 500 selected keys.');const start=Math.min(...records.map(r=>r.time));return{version:1,items:records.map(r=>{const copy=structuredClone(r);copy.relative=r.time-start;if(r.kind==='body'){const v=stateAt(o,r.time);for(const f of Object.keys(copy.data.v))copy.data.v[f]=v[f]}return copy})}}
document.body.insertAdjacentHTML('beforeend','<dialog id="batchKeysDialog"><div class="tool-heading"><h2>Edit multiple keyframes</h2><button id="closeBatchKeys">Close</button></div><p class="note">Choose a layer and select pose, body, part, expression, view, hand or word keys. Each edit is checked before applying and can be undone once. Pasting replaces matching-time keys; optional position offset keeps the target’s placement.</p><div class="rig-tools"><label>Layer<select id="batchKeyLayer"></select></label><label>Track<select id="batchKeyKind"><option value="all">All keys</option><option value="pose">Pose</option><option value="body">Body</option><option value="part">Object parts</option><option value="expression">Expressions</option><option value="view">Views</option><option value="hand">Hands</option><option value="word">Words</option></select></label><button id="selectAllBatchKeys">Select shown</button><button id="clearBatchKeys">Clear selection</button><button id="copyBatchKeys">Copy selected</button></div><div id="batchKeyChoices" class="batch-choice-list"></div><div class="rig-tools"><label>Shift (s)<input id="batchKeyShift" type="number" step="0.033333" value="0.5"></label><button id="shiftBatchKeys">Shift selected</button><label>Paste at (s)<input id="batchKeyPasteAt" type="number" min="0" step="0.033333" value="0"></label><label><input id="batchKeyKeepPosition" type="checkbox" checked> Keep target position</label><button id="pasteBatchKeys">Paste keys</button><button id="deleteBatchKeys">Delete selected</button></div><p id="batchKeyStatus" role="status" class="note"></p></dialog>');
function batchKeyActor(){return current().objects.find(o=>o.id===$('batchKeyLayer').value)}
function shownBatchKeys(){const o=batchKeyActor(),kind=$('batchKeyKind').value;return o?layerKeyRecords(o).filter(r=>kind==='all'||r.kind===kind):[]}
function renderBatchKeyChoices(){const list=$('batchKeyChoices');list.replaceChildren();const keys=shownBatchKeys();for(const key of keys.slice(0,1000)){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=batchKeySelection.has(key.ref);input.dataset.keyRef=key.ref;input.onchange=()=>{input.checked?batchKeySelection.add(key.ref):batchKeySelection.delete(key.ref);$('batchKeyStatus').textContent=batchKeySelection.size+' keys selected.'};label.append(input,document.createTextNode(key.time.toFixed(3)+'s · '+key.kind+' · '+key.track));list.append(label)}$('batchKeyStatus').textContent=batchKeySelection.size+' selected · '+keys.length+' matching keys'+(keys.length>1000?' · displaying first 1,000; filter a track to narrow the list.':'')}
async function openBatchKeys(){if(recording||audioBusy)return;if(!current().objects.length)return toast('Add a layer before editing its keyframes.');stop();await keyClipboardReady;const select=$('batchKeyLayer');select.replaceChildren();for(const o of current().objects){const option=document.createElement('option');option.value=o.id;option.textContent=o.name+(o.locked?' · locked':'');select.append(option)}if(object())select.value=object().id;batchKeySelection.clear();$('batchKeyPasteAt').value=+time.toFixed(3);renderBatchKeyChoices();$('batchKeysDialog').showModal()}
function commitKeyEdit(operation){try{const o=batchKeyActor(),records=layerKeyRecords(o).filter(r=>batchKeySelection.has(r.ref)),copy=buildKeyEdit(o,records,operation,{delta:+$('batchKeyShift').value,at:+$('batchKeyPasteAt').value,keepPosition:$('batchKeyKeepPosition').checked});Object.assign(o,copy);save();render();batchKeySelection.clear();renderBatchKeyChoices();$('batchKeyStatus').textContent='Keys updated. Undo restores this edit.'}catch(e){$('batchKeyStatus').textContent=e.message}}
$('openBatchKeys').onclick=openBatchKeys;$('closeBatchKeys').onclick=()=>$('batchKeysDialog').close();$('batchKeyLayer').onchange=()=>{batchKeySelection.clear();renderBatchKeyChoices()};$('batchKeyKind').onchange=()=>{batchKeySelection.clear();renderBatchKeyChoices()};$('selectAllBatchKeys').onclick=()=>{batchKeySelection=new Set(shownBatchKeys().slice(0,500).map(r=>r.ref));renderBatchKeyChoices()};$('clearBatchKeys').onclick=()=>{batchKeySelection.clear();renderBatchKeyChoices()};$('copyBatchKeys').onclick=async()=>{try{const o=batchKeyActor(),records=layerKeyRecords(o).filter(r=>batchKeySelection.has(r.ref));batchKeyClipboard=copyLayerKeys(o,records);await workspacePut('keyClipboard',batchKeyClipboard);$('batchKeyStatus').textContent=records.length+' keys copied. Choose a target layer and paste time.'}catch(e){$('batchKeyStatus').textContent=e.message}};$('shiftBatchKeys').onclick=()=>commitKeyEdit('shift');$('pasteBatchKeys').onclick=()=>commitKeyEdit('paste');$('deleteBatchKeys').onclick=()=>commitKeyEdit('delete');
const keyClipboardReady=workspaceValue('keyClipboard').then(value=>{if(value?.version===1&&Array.isArray(value.items)&&value.items.length<=500&&value.items.every(r=>['pose','body','part','expression','view','hand','word'].includes(r.kind)&&Number.isFinite(r.relative)&&r.relative>=0&&r.data&&typeof r.track==='string'))batchKeyClipboard=value}).catch(()=>{});
